-- ---------------------------------------------------------------------------
-- Table: strategies_1
-- Stores available trading strategy definitions
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS strategies_1 (
    strategy_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    strategy_name   TEXT NOT NULL UNIQUE,
    strategy_type   TEXT NOT NULL DEFAULT 'day_trade',  -- day_trade | swing | scalp | momentum_burst
    description     TEXT,
    risk_level      TEXT NOT NULL DEFAULT 'medium',     -- low | medium | high | very_high
    timeframe       TEXT NOT NULL DEFAULT '1d',         -- 1h | 4h | 1d | 3d | 7d
    min_score       REAL NOT NULL DEFAULT 70.0,
    max_positions   INTEGER NOT NULL DEFAULT 5,
    default_stop_loss_pct   REAL NOT NULL DEFAULT 3.0,  -- percentage below entry
    default_take_profit_pct REAL NOT NULL DEFAULT 6.0,  -- percentage above entry
    commission_model TEXT NOT NULL DEFAULT 'questrade', -- questrade | ibkr | free
    prefer_cdr      INTEGER NOT NULL DEFAULT 1,         -- 1 = prefer CDRs when available
    is_active       INTEGER NOT NULL DEFAULT 1,
    created_at      TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
    generated_by    TEXT NOT NULL DEFAULT 'cursor_ai_agent'
);

-- ---------------------------------------------------------------------------
-- Table: portfolios_1
-- Stores portfolio configurations for each strategy
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS portfolios_1 (
    portfolio_id    INTEGER PRIMARY KEY AUTOINCREMENT,
    portfolio_name  TEXT NOT NULL UNIQUE,
    strategy_id     INTEGER NOT NULL,
    initial_capital REAL NOT NULL DEFAULT 10000.0,
    current_capital REAL NOT NULL DEFAULT 10000.0,
    currency        TEXT NOT NULL DEFAULT 'CAD',        -- CAD | USD
    max_risk_per_trade_pct  REAL NOT NULL DEFAULT 2.0,  -- max % of capital per trade
    max_daily_loss_pct      REAL NOT NULL DEFAULT 5.0,  -- max % daily drawdown
    is_paper_trading        INTEGER NOT NULL DEFAULT 1, -- 1 = paper trading mode
    broker          TEXT NOT NULL DEFAULT 'questrade',
    account_type    TEXT NOT NULL DEFAULT 'tfsa',       -- tfsa | rrsp | margin | cash
    is_active       INTEGER NOT NULL DEFAULT 1,
    created_at      TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
    generated_by    TEXT NOT NULL DEFAULT 'cursor_ai_agent',
    FOREIGN KEY (strategy_id) REFERENCES strategies_1(strategy_id)
);

-- ---------------------------------------------------------------------------
-- Table: trading_signals_1
-- Stores generated trade signals / picks from the Miracle engine
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS trading_signals_1 (
    signal_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    symbol          TEXT NOT NULL,
    company_name    TEXT,
    exchange        TEXT,                               -- NYSE | NASDAQ | TSX | NEO
    is_cdr          INTEGER NOT NULL DEFAULT 0,         -- 1 = Canadian Depositary Receipt
    cdr_symbol      TEXT,                               -- e.g., AAPL.NE for Apple CDR
    strategy_id     INTEGER NOT NULL,
    signal_type     TEXT NOT NULL DEFAULT 'LONG',       -- LONG | SHORT
    rating          TEXT NOT NULL DEFAULT 'BUY',        -- STRONG_BUY | BUY | HOLD | SELL
    score           REAL NOT NULL DEFAULT 0.0,          -- 0-100 composite score
    
    -- Price levels
    current_price   REAL NOT NULL,
    entry_price     REAL NOT NULL,                      -- recommended entry (with slippage)
    stop_loss       REAL NOT NULL,
    take_profit_1   REAL NOT NULL,                      -- conservative TP
    take_profit_2   REAL,                               -- aggressive TP
    take_profit_3   REAL,                               -- moonshot TP
    
    -- Risk/Reward
    risk_reward_ratio   REAL NOT NULL DEFAULT 0.0,
    position_size_pct   REAL NOT NULL DEFAULT 0.0,      -- % of portfolio
    estimated_risk_usd  REAL NOT NULL DEFAULT 0.0,
    estimated_reward_usd REAL NOT NULL DEFAULT 0.0,
    
    -- Fee calculation
    commission_cost     REAL NOT NULL DEFAULT 0.0,      -- estimated total commission (buy + sell)
    fx_fee_cost         REAL NOT NULL DEFAULT 0.0,      -- estimated FX conversion fee
    net_profit_target   REAL NOT NULL DEFAULT 0.0,      -- profit after fees at TP1
    uses_cdr_savings    INTEGER NOT NULL DEFAULT 0,     -- 1 = saved money via CDR
    
    -- Technical indicators
    rsi_14          REAL,
    volume_surge    REAL,                               -- current vol / avg vol
    atr_14          REAL,                               -- Average True Range
    sma_20          REAL,
    sma_50          REAL,
    sma_200         REAL,
    macd_signal     TEXT,                               -- bullish | bearish | neutral
    bollinger_pos   TEXT,                               -- upper | middle | lower | squeeze
    vwap            REAL,
    
    -- Catalyst / reason
    catalyst        TEXT,                               -- why this pick is expected to move
    confidence      TEXT NOT NULL DEFAULT 'medium',     -- low | medium | high | very_high
    timeframe       TEXT NOT NULL DEFAULT '1d',
    expiry          TEXT,                               -- signal expiry datetime
    
    -- Tracking
    status          TEXT NOT NULL DEFAULT 'active',     -- active | triggered | stopped | expired | closed
    actual_entry    REAL,
    actual_exit     REAL,
    actual_pnl      REAL,
    exit_reason     TEXT,                               -- tp_hit | sl_hit | manual | expired
    
    picked_at       TEXT NOT NULL DEFAULT (datetime('now')),
    closed_at       TEXT,
    pick_hash       TEXT,                               -- immutable hash for audit trail
    
    generated_by    TEXT NOT NULL DEFAULT 'cursor_ai_agent',
    FOREIGN KEY (strategy_id) REFERENCES strategies_1(strategy_id)
);

-- ---------------------------------------------------------------------------
-- Table: signal_scores_breakdown_1
-- Detailed score breakdown for each signal
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS signal_scores_breakdown_1 (
    breakdown_id    INTEGER PRIMARY KEY AUTOINCREMENT,
    signal_id       INTEGER NOT NULL,
    component_name  TEXT NOT NULL,          -- e.g. 'momentum', 'volume', 'trend', 'catalyst'
    component_score REAL NOT NULL DEFAULT 0.0,
    max_score       REAL NOT NULL DEFAULT 0.0,
    weight          REAL NOT NULL DEFAULT 1.0,
    notes           TEXT,
    FOREIGN KEY (signal_id) REFERENCES trading_signals_1(signal_id)
);

-- ---------------------------------------------------------------------------
-- Table: daily_scan_results_1
-- Raw scan results before filtering into signals
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS daily_scan_results_1 (
    scan_id         INTEGER PRIMARY KEY AUTOINCREMENT,
    scan_date       TEXT NOT NULL,
    symbol          TEXT NOT NULL,
    strategy_name   TEXT NOT NULL,
    raw_score       REAL NOT NULL DEFAULT 0.0,
    passed_filter   INTEGER NOT NULL DEFAULT 0,
    scan_data_json  TEXT,                   -- full indicator snapshot as JSON
    scanned_at      TEXT NOT NULL DEFAULT (datetime('now'))
);

-- ---------------------------------------------------------------------------
-- Table: performance_log_1
-- Historical performance tracking for strategy validation
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS performance_log_1 (
    log_id          INTEGER PRIMARY KEY AUTOINCREMENT,
    date            TEXT NOT NULL,
    strategy_id     INTEGER NOT NULL,
    portfolio_id    INTEGER,
    total_signals   INTEGER NOT NULL DEFAULT 0,
    wins            INTEGER NOT NULL DEFAULT 0,
    losses          INTEGER NOT NULL DEFAULT 0,
    win_rate        REAL NOT NULL DEFAULT 0.0,
    total_pnl       REAL NOT NULL DEFAULT 0.0,
    avg_return_pct  REAL NOT NULL DEFAULT 0.0,
    max_drawdown_pct REAL NOT NULL DEFAULT 0.0,
    sharpe_ratio    REAL,
    notes           TEXT,
    generated_by    TEXT NOT NULL DEFAULT 'cursor_ai_agent',
    FOREIGN KEY (strategy_id) REFERENCES strategies_1(strategy_id),
    FOREIGN KEY (portfolio_id) REFERENCES portfolios_1(portfolio_id)
);

