-- =============================================================================
-- ADAPTIVE ORACLE TABLES (Self-Adjusting Learning Algorithm)
-- Generated by: Cursor AI Agent (cursor-generated)
-- These tables power the "sister algorithm" that learns from failures and
-- self-adjusts its scoring weights day by day.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Table: adaptive_weights_1
-- Stores the evolving scoring weights for the Adaptive Oracle algorithm.
-- Each row is a snapshot of the weight vector at a point in time.
-- The Oracle adjusts these weights after every completed trade cycle.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS adaptive_weights_1 (
    weight_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    strategy_id     INTEGER NOT NULL,
    epoch           INTEGER NOT NULL DEFAULT 0,          -- learning epoch counter
    -- Scoring component weights (sum to 1.0)
    w_momentum      REAL NOT NULL DEFAULT 0.20,          -- RSI + price momentum
    w_volume        REAL NOT NULL DEFAULT 0.20,          -- volume surge / profile
    w_trend         REAL NOT NULL DEFAULT 0.15,          -- SMA alignment / stage
    w_volatility    REAL NOT NULL DEFAULT 0.10,          -- ATR / Bollinger regime
    w_catalyst      REAL NOT NULL DEFAULT 0.10,          -- breakout / squeeze / gap
    w_sentiment     REAL NOT NULL DEFAULT 0.05,          -- market sentiment proxy
    w_sector_str    REAL NOT NULL DEFAULT 0.05,          -- sector relative strength
    w_risk_reward   REAL NOT NULL DEFAULT 0.10,          -- R:R quality
    w_fee_efficiency REAL NOT NULL DEFAULT 0.05,         -- CDR / cost efficiency
    -- Meta
    learning_rate   REAL NOT NULL DEFAULT 0.05,          -- how aggressively weights shift
    decay_factor    REAL NOT NULL DEFAULT 0.95,          -- exponential decay on old data
    confidence      REAL NOT NULL DEFAULT 0.5,           -- model confidence (0-1)
    total_trades_seen INTEGER NOT NULL DEFAULT 0,
    total_wins      INTEGER NOT NULL DEFAULT 0,
    total_losses    INTEGER NOT NULL DEFAULT 0,
    win_rate        REAL NOT NULL DEFAULT 0.0,
    avg_pnl         REAL NOT NULL DEFAULT 0.0,
    sharpe_estimate REAL,
    is_active       INTEGER NOT NULL DEFAULT 1,
    created_at      TEXT NOT NULL DEFAULT (datetime('now')),
    notes           TEXT,
    generated_by    TEXT NOT NULL DEFAULT 'cursor_ai_agent',
    FOREIGN KEY (strategy_id) REFERENCES strategies_1(strategy_id)
);

-- ---------------------------------------------------------------------------
-- Table: feedback_loop_1
-- Stores every completed trade outcome and the weight adjustment applied.
-- This is the "memory" of the Oracle: what worked, what didn't, and what
-- changed as a result.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS feedback_loop_1 (
    feedback_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    signal_id       INTEGER NOT NULL,
    strategy_id     INTEGER NOT NULL,
    symbol          TEXT NOT NULL,
    -- Outcome
    outcome         TEXT NOT NULL,                       -- 'win' | 'loss' | 'breakeven'
    entry_price     REAL NOT NULL,
    exit_price      REAL NOT NULL,
    pnl             REAL NOT NULL DEFAULT 0.0,
    pnl_pct         REAL NOT NULL DEFAULT 0.0,
    hold_duration_hours REAL NOT NULL DEFAULT 0.0,
    exit_reason     TEXT,                                -- 'tp_hit' | 'sl_hit' | 'expired' | 'manual'
    -- Score at time of pick
    original_score  REAL NOT NULL DEFAULT 0.0,
    -- Component scores at time of pick (for gradient analysis)
    c_momentum      REAL NOT NULL DEFAULT 0.0,
    c_volume        REAL NOT NULL DEFAULT 0.0,
    c_trend         REAL NOT NULL DEFAULT 0.0,
    c_volatility    REAL NOT NULL DEFAULT 0.0,
    c_catalyst      REAL NOT NULL DEFAULT 0.0,
    c_sentiment     REAL NOT NULL DEFAULT 0.0,
    c_sector_str    REAL NOT NULL DEFAULT 0.0,
    c_risk_reward   REAL NOT NULL DEFAULT 0.0,
    c_fee_efficiency REAL NOT NULL DEFAULT 0.0,
    -- Weight adjustment applied after this outcome
    delta_momentum  REAL NOT NULL DEFAULT 0.0,
    delta_volume    REAL NOT NULL DEFAULT 0.0,
    delta_trend     REAL NOT NULL DEFAULT 0.0,
    delta_volatility REAL NOT NULL DEFAULT 0.0,
    delta_catalyst  REAL NOT NULL DEFAULT 0.0,
    delta_sentiment REAL NOT NULL DEFAULT 0.0,
    delta_sector_str REAL NOT NULL DEFAULT 0.0,
    delta_risk_reward REAL NOT NULL DEFAULT 0.0,
    delta_fee_efficiency REAL NOT NULL DEFAULT 0.0,
    -- Epoch before and after
    epoch_before    INTEGER NOT NULL DEFAULT 0,
    epoch_after     INTEGER NOT NULL DEFAULT 0,
    -- Market context at time of trade
    market_regime   TEXT,                                -- 'bull' | 'bear' | 'sideways' | 'volatile'
    spy_change_pct  REAL,                                -- S&P 500 change during hold
    vix_level       REAL,                                -- VIX at entry
    -- Meta
    analyzed_at     TEXT NOT NULL DEFAULT (datetime('now')),
    generated_by    TEXT NOT NULL DEFAULT 'cursor_ai_agent',
    FOREIGN KEY (signal_id) REFERENCES trading_signals_1(signal_id),
    FOREIGN KEY (strategy_id) REFERENCES strategies_1(strategy_id)
);

-- ---------------------------------------------------------------------------
-- Table: regime_memory_1
-- Stores market regime snapshots so the Oracle adjusts differently in
-- bull vs bear vs sideways markets.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS regime_memory_1 (
    regime_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    date            TEXT NOT NULL,
    spy_price       REAL,
    spy_sma_200     REAL,
    spy_rsi         REAL,
    vix_level       REAL,
    regime          TEXT NOT NULL DEFAULT 'unknown',     -- 'bull' | 'bear' | 'sideways' | 'volatile'
    regime_score    REAL NOT NULL DEFAULT 0.0,           -- 0-100 confidence in regime
    sector_leader   TEXT,                                -- which sector is strongest
    sector_laggard  TEXT,                                -- which sector is weakest
    breadth_pct     REAL,                                -- % of stocks above 200 SMA
    notes           TEXT,
    generated_by    TEXT NOT NULL DEFAULT 'cursor_ai_agent'
);

-- ---------------------------------------------------------------------------
-- Table: oracle_predictions_1
-- The Oracle's own prediction log, separate from raw signals.
-- This tracks the "meta-prediction": how confident the Oracle was and
-- whether its confidence calibration was accurate.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS oracle_predictions_1 (
    prediction_id   INTEGER PRIMARY KEY AUTOINCREMENT,
    signal_id       INTEGER,
    symbol          TEXT NOT NULL,
    predicted_direction TEXT NOT NULL DEFAULT 'up',      -- 'up' | 'down' | 'flat'
    predicted_magnitude_pct REAL NOT NULL DEFAULT 0.0,   -- expected % move
    confidence_score REAL NOT NULL DEFAULT 0.0,          -- 0-100
    timeframe       TEXT NOT NULL DEFAULT '1d',
    -- Actual outcome (filled after close)
    actual_direction TEXT,
    actual_magnitude_pct REAL,
    prediction_error REAL,                               -- |predicted - actual|
    was_correct     INTEGER,                             -- 1 = direction was right
    -- Calibration
    calibration_bucket TEXT,                             -- 'high_conf_win', 'high_conf_loss', etc.
    -- Meta
    predicted_at    TEXT NOT NULL DEFAULT (datetime('now')),
    resolved_at     TEXT,
    generated_by    TEXT NOT NULL DEFAULT 'cursor_ai_agent',
    FOREIGN KEY (signal_id) REFERENCES trading_signals_1(signal_id)
);

-- ---------------------------------------------------------------------------
-- Table: symbol_memory_1
-- Per-symbol historical memory: how well the Oracle has done on each ticker.
-- This allows it to avoid symbols where it consistently fails and favor
-- symbols where its model works well.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS symbol_memory_1 (
    memory_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    symbol          TEXT NOT NULL UNIQUE,
    times_picked    INTEGER NOT NULL DEFAULT 0,
    times_won       INTEGER NOT NULL DEFAULT 0,
    times_lost      INTEGER NOT NULL DEFAULT 0,
    win_rate        REAL NOT NULL DEFAULT 0.0,
    avg_pnl_pct     REAL NOT NULL DEFAULT 0.0,
    best_pnl_pct    REAL NOT NULL DEFAULT 0.0,
    worst_pnl_pct   REAL NOT NULL DEFAULT 0.0,
    avg_hold_hours  REAL NOT NULL DEFAULT 0.0,
    -- Which strategies work best for this symbol
    best_strategy_id INTEGER,
    worst_strategy_id INTEGER,
    -- Reliability score: higher = Oracle trusts its read on this symbol more
    reliability_score REAL NOT NULL DEFAULT 50.0,        -- 0-100
    -- Blacklist
    is_blacklisted  INTEGER NOT NULL DEFAULT 0,          -- 1 = Oracle avoids this symbol
    blacklist_reason TEXT,
    last_picked     TEXT,
    last_updated    TEXT NOT NULL DEFAULT (datetime('now')),
    generated_by    TEXT NOT NULL DEFAULT 'cursor_ai_agent'
);

